`regression_test.go`:

```go
package main

import "testing"

func fixture() Pipeline {
    items := []Item{
        {Key: "item-1", Value: "a"},
        {Key: "item-2", Value: "b"},
        {Key: "item-3", Value: "c"},
    }
    return Pipeline{Steps: []Step{
        {Name: "fetch"},
        {Name: "each", ForEach: &ForEach{
            Items:    items,
            Template: []Step{{Name: "summarize"}},
        }},
    }}
}

// Bug repro: nested template reuses "run@1" -> completed with empty output.
func TestRepro_UnscopedNestedCollides(t *testing.T) {
    eng := NewEngine()
    store := NewCheckpointStore()
    r := &Runner{RunID: "run", Engine: eng, Store: store}

    out := r.RunUnscoped(fixture())

    var nested []Result
    for _, res := range out {
        if res.Node == "summarize" {
            nested = append(nested, res)
        }
    }
    if len(nested) != 3 {
        t.Fatalf("want 3 nested results, got %d", len(nested))
    }
    for i, res := range nested {
        if res.Status != StatusCompleted {
            t.Fatalf("nested[%d] status = %s, want completed", i, res.Status)
        }
        if res.Output != "" {
            t.Fatalf("nested[%d] output = %q, want empty (bug should reproduce)", i, res.Output)
        }
        if res.RunID != "run@1" {
            t.Fatalf("nested[%d] runID = %q, want colliding run@1", i, res.RunID)
        }
    }
    if store.Len() != 1 {
        t.Fatalf("checkpoint rows = %d, want 1 (iteration rows missing)", store.Len())
    }
}

// Regression: fixed foreach never aliases or mutates top-level entries.
func TestRunner_ForEachTouchesNoTopLevelEntries(t *testing.T) {
    eng := NewEngine()
    store := NewCheckpointStore()
    r := &Runner{RunID: "run", Engine: eng, Store: store}

    out := r.Run(fixture())

    top := map[string]Result{}
    for _, res := range out {
        if res.Node == "fetch" {
            top[res.RunID] = res
        }
    }
    if len(top) != 1 {
        t.Fatalf("want exactly 1 top-level entry, got %d", len(top))
    }
    if _, ok := top["run@1"]; !ok {
        t.Fatalf("top-level entry run@1 missing: %#v", top)
    }

    var nested []Result
    seen := map[string]bool{}
    for _, res := range out {
        if res.Node != "summarize" {
            continue
        }
        nested = append(nested, res)
        if res.RunID == "run@1" || res.RunID == "run@2" {
            t.Fatalf("nested node touched a top-level run ID: %q", res.RunID)
        }
        if res.Output == "" {
            t.Fatalf("nested %q returned empty output", res.RunID)
        }
        seen[res.RunID] = true
    }
    if len(nested) != 3 {
        t.Fatalf("want 3 nested results, got %d", len(nested))
    }
    if len(seen) != 3 {
        t.Fatalf("want 3 distinct iteration run scopes, got %d (%v)", len(seen), seen)
    }
    if store.Len() != 4 {
        t.Fatalf("checkpoint rows = %d, want 4 (1 top-level + 3 iterations)", store.Len())
    }
    if got := len(store.RunIDs()); got < 4 {
        t.Fatalf("distinct run IDs = %d, want >= 4", got)
    }
}

// Regression: scoped nested node survives an already-completed parent step.
func TestAdapterScopedNestedScopeSurvivesCompletedParentStep(t *testing.T) {
    eng := NewEngine()
    store := NewCheckpointStore()
    a := &Adapter{Engine: eng, Store: store}

    parent := a.RunNode("run", "", "step1")
    if parent.Output == "" || parent.Cached {
        t.Fatalf("parent first run: %#v", parent)
    }
    parentAgain := a.RunNode("run", "", "step1")
    if !parentAgain.Cached {
        t.Fatalf("parent second run should be a cache hit: %#v", parentAgain)
    }

    parentID := EngineRunID("run", "", "step1")
    nestedID := EngineRunID("run", "each@item-1", "step1")
    if parentID == nestedID {
        t.Fatalf("scope was lost: parent and nested IDs both %q", parentID)
    }
    nested := a.RunNode("run", "each@item-1", "step1")
    if nested.Cached {
        t.Fatalf("scoped nested node incorrectly served from parent cache: %#v", nested)
    }
    if nested.Output == "" {
        t.Fatalf("scoped nested node returned empty output: %#v", nested)
    }
    if nested.RunID != nestedID {
        t.Fatalf("nested runID = %q, want %q", nested.RunID, nestedID)
    }

    aliased := a.RunNode("run", "", "step1")
    if !aliased.Cached {
        t.Fatalf("unscoped nested node should have aliased the parent: %#v", aliased)
    }
}

// Mirrors REAL_MODE=0 boardctl-sync: 15 iterations -> 15 distinct run IDs.
func TestRunner_FifteenIterationsFifteenRunIDs(t *testing.T) {
    items := make([]Item, 15)
    for i := range items {
        items[i] = Item{Key: string(rune('a' + i)), Value: "v"}
    }
    p := Pipeline{Steps: []Step{{Name: "each", ForEach: &ForEach{
        Items: items, Template: []Step{{Name: "work"}},
    }}}}
    eng := NewEngine()
    store := NewCheckpointStore()
    r := &Runner{RunID: "board", Engine: eng, Store: store}
    out := r.Run(p)
    if len(out) != 15 {
        t.Fatalf("results = %d, want 15", len(out))
    }
    if store.Len() != 15 {
        t.Fatalf("checkpoint rows = %d, want 15", store.Len())
    }
    if ids := store.RunIDs(); len(ids) != 15 {
        t.Fatalf("distinct run IDs = %d, want 15 (%v)", len(ids), ids)
    }
}
```

## 5. Verification

### 5.1 Build, vet, race suite

```bash
cd /tmp/dagger-repro
gofmt -l .          # must print nothing
go vet ./...        # must be clean
go test -race -v ./...
```

Observed output:

```
=== RUN   TestRunner_FifteenIterationsFifteenRunIDs
--- PASS: TestRunner_FifteenIterationsFifteenRunIDs (0.00s)
=== RUN   TestRepro_UnscopedNestedCollides
--- PASS: TestRepro_UnscopedNestedCollides (0.00s)
=== RUN   TestRunner_ForEachTouchesNoTopLevelEntries
--- PASS: TestRunner_ForEachTouchesNoTopLevelEntries (0.00s)
=== RUN   TestAdapterScopedNestedScopeSurvivesCompletedParentStep
--- PASS: TestAdapterScopedNestedScopeSurvivesCompletedParentStep (0.00s)
PASS
ok  	daggerrepro	1.013s
```

The results prove all four required properties:

* `TestRepro_UnscopedNestedCollides` reproduces the bug: nested terminals are `Status=completed` with `Output=""`, and only 1 checkpoint row (the top-level) exists.
* `TestRunner_ForEachTouchesNoTopLevelEntries` proves nested nodes never use `run@1`/`run@2`, each iteration gets a distinct scope, and every iteration checkpoint is written.
* `TestAdapterScopedNestedScopeSurvivesCompletedParentStep` proves a scoped nested node is not served from the completed parent's cache.
* `TestRunner_FifteenIterationsFifteenRunIDs` proves 15 iterations yield 15 checkpoint rows under 15 distinct run IDs.

### 5.2 Against the real tree

```bash
go test -race ./src/runner/... ./src/mcp/...
go test -race ./...
```

Expected: `TestRunner_ForEachTouchesNoTopLevelEntries` and `TestAdapterScopedNestedScopeSurvivesCompletedParentStep` pass, as do all pre-existing resume / fresh-run / cache / checkpoint tests.

### 5.3 End-to-end (as run for the accepted fix)

```bash
REAL_MODE=0 boardctl-sync
```

Expected: `10/10` pass, and the checkpoint DB contains **15 iteration checkpoint rows under 15 distinct run IDs** (verified by the `TestRunner_FifteenIterationsFifteenRunIDs` surrogate above).

### 5.4 Semantics checklist

| Semantic | Preserved? | Why |
|---|---|---|
| Completed-run caching | Yes | Cache still keyed by engine run ID; IDs are now unique per iteration. |
| Resume | Yes | Item key is stable, so a re-run resolves to the same scoped IDs and reuses completed sub-runs. |
| Fresh run | Yes | Deterministic IDs are recomputed; clearing the store yields a clean run. |
| Checkpoint | Yes | One row per iteration under its own run ID; no rows dropped. |
| Top-level integrity | Yes | Top-level IDs (`<run>@<step>`) are unchanged. |

## 6. Rollout / rollback

* **Rollout:** land the runner child-scope change first (it is the correctness fix), then the adapter ID-composition change. Keep the completed-run cache enabled throughout.
* **Rollback:** revert to the previous commit. Note that simply disabling the engine cache is **not** an acceptable rollback — it would mask the symptom while breaking resume and checkpoint semantics.
* **Guardrail:** `TestRunner_ForEachTouchesNoTopLevelEntries` fails if anyone reintroduces an unscoped nested loop; `TestAdapterScopedNestedScopeSurvivesCompletedParentStep` fails if the adapter ever drops the scope when composing engine run IDs.
